 "content": "def transform(grid):
    # Count disconnected objects of colors 3 and 2, then pack their color
    # markers in row-major order into a 2x3 result.
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {3: 0, 2: 0}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in counts or (r, c) in seen:
                continue
            counts[color] += 1
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
    values = [3] * counts[3] + [2] * counts[2]
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
